#[test]
fn test_never_and_offline_win_over_every_hook() {
    crate::testport::assert_eq(ad_pack_action(0, pfetch_never(), 0, 1, pdec_fetch()), pact_unread(), "never: a fetch answer is not honoured");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_never(), 0, 1, pdec_provide()), pact_unread(), "never: nor a provide");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_never(), 0, 1, pdec_substitute()), pact_unread(), "never: nor a substitute");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_never(), 0, 0, 0), pact_unread(), "never with no hook: unread");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_auto(), 1, 1, pdec_fetch()), pact_unread(), "EMON_OFFLINE=1 in auto: unread");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_auto(), 1, 0, 0), pact_unread(), "EMON_OFFLINE=1 with no hook: unread");
    crate::testport::assert_eq(ad_pack_action(0, pfetch_cache(), 1, 1, pdec_provide()), pact_unread(), "EMON_OFFLINE=1 in cache: unread");
    crate::testport::assert_eq(ad_asks_hook(0, pfetch_never(), 0, 1), 0, "the hook is not even asked under never");
    crate::testport::assert_eq(ad_asks_hook(0, pfetch_auto(), 1, 1), 0, "nor offline");
}
