    crate::testport::assert_eq(ad_resolve(pcls_macos(), pkf_osd(), langs, engs, installed, out), pkerr_ok(), "with OSD installed");
    crate::testport::assert_eq(ad_verdict(out, pfetch_never(), 0), pver_ready(), "ready");
